/// A reconnect envelope is replayed when its sequence is not newer than the committed watermark.
pub fn is_replayed(sequence: u64, committed: u64) -> bool {
    sequence <= committed
}

/// An accepted envelope advances the committed watermark to that envelope's sequence.
pub fn next_committed(sequence: u64) -> u64 {
    sequence
}

