/// 会话结束时，临时投影必须使用 Option::take 转移并清空代际标识。
pub fn detach_generation(generation: &mut Option<u64>) -> Option<u64> {
    generation.take()
}

/// A release is counted only when a projection generation actually existed.
pub fn released_delta(detached: &Option<u64>) -> usize {
    usize::from(detached.is_some())
}

