/// Capacity exists only while pending work is strictly below the configured ceiling.
pub fn has_capacity(pending: usize, ceiling: usize) -> bool {
    pending < ceiling
}

/// A successful reservation increments the pending count exactly once.
pub fn record_reservation(pending: &mut usize) {
    *pending += 1;
}

