use wsr_generation_fixture::solution::try_reserve;

#[test]
fn reserves_once_below_the_ceiling() {
    let mut pending = 7;
    assert!(try_reserve(&mut pending));
    assert_eq!(pending, 8);
}

#[test]
fn refuses_at_or_above_the_ceiling_without_mutation() {
    let mut at_limit = 8;
    assert!(!try_reserve(&mut at_limit));
    assert_eq!(at_limit, 8);
    let mut above_limit = 9;
    assert!(!try_reserve(&mut above_limit));
    assert_eq!(above_limit, 9);
}
